from z3 import *

n = 23
min_deg = 3
max_deg = 6

# Create edge variables
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f'e_{i}_{j}')

s = Solver()

# Degree constraints
for v in range(n):
    incident = []
    for u in range(n):
        if u != v:
            i, j = (u, v) if u < v else (v, u)
            incident.append(edges[(i,j)])
    s.add(Sum([If(e, 1, 0) for e in incident]) >= min_deg)
    s.add(Sum([If(e, 1, 0) for e in incident]) <= max_deg)

print("Added degree constraints")

# No triangles
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(i,k)])))

print("Added triangle constraints")

# No 4-cycles
count_4 = 0
for v1 in range(n):
    for v2 in range(v1+1, n):
        for v3 in range(v1+1, n):
            if v3 == v2:
                continue
            for v4 in range(v1+1, n):
                if v4 == v2 or v4 == v3:
                    continue
                # Need edges: (v1,v2), (v2,v3), (v3,v4), (v4,v1)
                e1 = edges[(v1,v2)]
                e2 = edges[(min(v2,v3), max(v2,v3))]
                e3 = edges[(min(v3,v4), max(v3,v4))]
                e4 = edges[(v1,v4)]
                s.add(Not(And(e1, e2, e3, e4)))
                count_4 += 1

print(f"Added {count_4} 4-cycle constraints")

# No 5-cycles
count_5 = 0
for v1 in range(n):
    for v2 in range(n):
        if v2 == v1: continue
        for v3 in range(n):
            if v3 in [v1, v2]: continue
            for v4 in range(n):
                if v4 in [v1, v2, v3]: continue
                for v5 in range(n):
                    if v5 in [v1, v2, v3, v4]: continue
                    # Only consider cycles where v1 is the smallest to avoid duplicates
                    if v1 != min(v1, v2, v3, v4, v5):
                        continue
                    # Check that v2 < v5 to avoid reflection duplicates
                    if v2 > v5:
                        continue
                    e1 = edges[(min(v1,v2), max(v1,v2))]
                    e2 = edges[(min(v2,v3), max(v2,v3))]
                    e3 = edges[(min(v3,v4), max(v3,v4))]
                    e4 = edges[(min(v4,v5), max(v4,v5))]
                    e5 = edges[(min(v5,v1), max(v5,v1))]
                    s.add(Not(And(e1, e2, e3, e4, e5)))
                    count_5 += 1

print(f"Added {count_5} 5-cycle constraints")
print(f"Total assertions: {len(s.assertions())}")

