def find_girth_detailed(graph, n):
    from collections import deque
    girth = float('inf')
    best_cycle = None

    for start in range(n):
        dist = {start: 0}
        parent = {start: None}
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent.get(v) != u:
                    # Found a back edge creating a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < girth:
                        girth = cycle_len
                        best_cycle = (start, u, v, dist[u], dist[v])

    return girth if girth != float('inf') else None, best_cycle

g, info = find_girth_detailed(graph, n)
print(f"Girth: {g}")
print(f"Cycle info: {info}")

