def find_all_cycles(graph, n, max_len):
    from collections import defaultdict
    cycles = []

    # DFS to find all simple cycles up to max_len
    def dfs(start, current, path, visited):
        for neighbor in graph[current]:
            if neighbor == start and len(path) >= 2:
                cycles.append(list(path) + [start])
            elif neighbor not in visited and len(path) < max_len:
                visited.add(neighbor)
                path.append(neighbor)
                dfs(start, neighbor, path, visited)
                path.pop()
                visited.remove(neighbor)

    for start in range(n):
        visited = {start}
        dfs(start, start, [start], visited)

    return cycles

