import random
from collections import defaultdict

n = 23
min_deg = 3
max_deg = 6

def check_cycle(graph, u, v):
    """Check if adding edge (u,v) would create a cycle of length < 6"""
    if v in graph[u]:
        return True

    from collections import deque
    visited = {u: 0}
    queue = deque([u])
    while queue:
        curr = queue.popleft()
        if visited[curr] >= 4:
            continue
        for neighbor in graph[curr]:
            if neighbor == v:
                if visited[curr] + 1 < 5:
                    return True
                continue
            if neighbor not in visited:
                visited[neighbor] = visited[curr] + 1
                queue.append(neighbor)
    return False

def find_girth_detailed(graph, n):
    from collections import deque
    girth = float('inf')

    for start in range(n):
        dist = {start: 0}
        parent = {start: None}
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v and parent.get(v) != u:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < girth:
                        girth = cycle_len

    return girth if girth != float('inf') else None

# Build graph
random.seed(42)
for attempt in range(10000):
    graph = defaultdict(set)

    all_edges = [(i,j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(all_edges)

    for u, v in all_edges:
        if len(graph[u]) >= max_deg or len(graph[v]) >= max_deg:
            continue
        if not check_cycle(graph, u, v):
            graph[u].add(v)
            graph[v].add(u)

    min_degree = min(len(graph[v]) for v in range(n))
    if min_degree >= min_deg:
        g = find_girth_detailed(graph, n)
