def find_short_cycles(graph, n):
    cycles_3 = set()
    cycles_4 = set()
    cycles_5 = set()

    for start in range(n):
        for n1 in graph[start]:
            if n1 <= start:
                continue
            for n2 in graph[n1]:
                if n2 <= start or n2 == n1:
                    continue
                # Check triangle
                if start in graph[n2]:
                    cycles_3.add(tuple(sorted([start, n1, n2])))

                for n3 in graph[n2]:
                    if n3 <= start or n3 in [n1, n2]:
                        continue
                    # Check 4-cycle
                    if start in graph[n3] and n1 not in [n3]:
                        cycles_4.add(tuple(sorted([start, n1, n2, n3])))

                    for n4 in graph[n3]:
                        if n4 <= start or n4 in [n1, n2, n3]:
                            continue
                        # Check 5-cycle
                        if start in graph[n4] and n1 not in [n3, n4] and n2 not in [n4]:
                            cycles_5.add(tuple(sorted([start, n1, n2, n3, n4])))

    return cycles_3, cycles_4, cycles_5

